insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'audit-hub','in-progress','high','Audit Hub: one place for everything audit','Sean (Nov 5 Hot Lab): one page for everything audit, where people submit audit fixes and find what is needed. Lives on the District Web Team hub as well. Lets Sean and the District Web Team see submitted fixes and still-stuck questions. Includes the Still-stuck queue (bcps_audit_questions: 9 open as of Nov 4).','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/bcps-audit-error-guide',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='audit-hub');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'still-stuck-queue-visibility','in-progress','high','Still-stuck questions: not visible in navigation','Sean could not find submitted still-stuck questions. Found: they are saved (9 open as of Nov 4) and viewable at /audit-questions for admins, but no navigation links to that page. Patricia Sapp saw "waiting for an answer from District Web Team" on her own item. Fix: link the queue from the audit hub and the District Web Team hub. Verify with a signed-in admin.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/bcps-audit-error-guide',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='still-stuck-queue-visibility');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'audit-message-wording','in-progress','high','Audit messages say what is wrong','Nov 5 Hot Lab: audit messages are vague (Patricia Sapp: an image or contracts flagged with no detail). Rewrite each audit message to name the problem, where it is, and the fix. Start with the top flagged rules. Coordinate with the audit-followups-nov-3 assignment.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/bcps-audit-error-guide',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='audit-message-wording');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'certification-page','in-progress','high','Certification page (District Web Team hub, Department section)','Approved by Sean (Nov 5). First build: tiles for Complete, 90 to 99 percent, below 90 percent, and Not started, each with a scrollable list, plus a leaderboard tile. Tabs: Outreach (campaign tiles; templates later) and Roster (sub-tabs: Almost done, In progress, Not started, Not yet completed). Lives under the Department section of the District Web Team hub. Later: connect to outreach so messages go out as a campaign.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/wcm-community-hub',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='certification-page');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'department-wcm-overview','in-progress','high','Department WCM Overview: combine the three pages','Approved by Sean (Nov 5). One page for WCMs and directors replacing the separate website review, audit process, analytics, Hot Lab notes and widgets pages. At a glance: certification status and how far from certified, next quarterly meeting, open actions. Audit window explained, with booking from the page. Analytics access with a short how-to. Hot Labs and widgets access. Meeting-prep checklist. Schedule button opens only when the audit is complete. Sean decided: the post-audit meeting is about marketing, not the audit. WCM required, director encouraged.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/wcm-department',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='department-wcm-overview');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'pdf-checker-fixer','in-progress','high','PDF checker and fixer (feasibility first)','Sean approved the feasibility memo (Nov 5). Tool: upload or link any PDF, check accessibility, and one button to fix a non-accessible file. Path: production first, then a website widget, then embed in the audit. Gate: if a page has more than 10 documents, stop and ask Sean before scanning. Linked PDFs audit section is redone once the tool is live. Deliver the feasibility memo first; no build until Sean approves it.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/district-web-team-tools',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='pdf-checker-fixer');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'academics-overview-page','pending','medium','Build out the Academics overview page','Sean (Nov 5 Hot Lab): the Academics top-level page has no content. An Academics overview page needs to be built out. Sub-pages need a link back to the overview, or the navigation loses it (Finalsite quirk). Sean to take the build, or assign it.','Sean A. Russell',NULL::date,'https://bcpsmarcomm.com/playbooks/bcps-feedback',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='academics-overview-page');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'heading-and-adobe-articles','pending','medium','Resource articles: heading sizes and Adobe how-to','Sean (Nov 5 Hot Lab): write an article on heading sizes and heading order if one does not exist, and check whether an Adobe how-to exists. Put both in the resources section and make them easy to find. Link them from the course, the audit, and the Department WCM Overview.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/bcps-feedback',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='heading-and-adobe-articles');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'department-website-path','pending','medium','Departments without a website: path to one','Nov 5 Hot Lab (Ernesto Gonzalez, Patricia Sapp follow-up): a department with no website first has its director align with the other directors. ISD direction on department-level sites is still an open question for leadership. Once the director agrees: Sean schedules a crash course, the WCM builds, brings it to Hot Lab for feedback, Sean does a once-over, the WCM publishes, and ISD main-page placement is worked out.','Sean A. Russell',NULL::date,'https://bcpsmarcomm.com/playbooks/director-department',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='department-website-path');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'public-school-impact-report','pending','low','Public School Impact Application: report from submissions','Sean (Nov 5 Hot Lab) described the application as the new intake for Facility and Real Estate Planning: pay on the e-store, submit the form with receipt, site plan and survey, sign, then the WCM reviews and approves from the back end, with a deadline reminder five days out. Sean may build a formal report from submissions. Not started.','Logan',NULL::date,'https://bcpsmarcomm.com/playbooks/bcps-feedback',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='public-school-impact-report');
insert into public.bcps_assignment_tags (assignment_slug, status, priority, title_override, description_override, lead_override, deadline_date, playbook_url, added_at, updated_at) select 'cert-congrats-message','in-progress','high','Certification status message to all WCMs (Fri Nov 6, 9 AM)','Draft today (Nov 5). Tone: thanks to everyone who finished; a few still outstanding are being contacted individually by Sean; access for anyone not finished comes off Monday, Nov 9. Sean approves the text, then it is scheduled for Friday, Nov 6, 9 AM. Not sent until Sean approves.','Logan','2026-11-06'::date,'https://bcpsmarcomm.com/playbooks/bcps-wcm-cert-followup-2026-11-03',now(),now() where not exists (select 1 from public.bcps_assignment_tags where assignment_slug='cert-congrats-message');
insert into public.bcps_assignment_notes (assignment_slug, note_text, author) select 'canvas-course-departments','Nov 5 Hot Lab: deadline day, 53 of 77 registered at the start. No extensions. Access comes off Monday for anyone not finished. Congratulations and status message to all WCMs scheduled Fri Nov 6, 9 AM, once Sean approves the text. Confirm the Monday access rule replaces the Oct 29 note.','Logan' where not exists (select 1 from public.bcps_assignment_notes where assignment_slug='canvas-course-departments' and note_text='Nov 5 Hot Lab: deadline day, 53 of 77 registered at the start. No extensions. Access comes off Monday for anyone not finished. Congratulations and status message to all WCMs scheduled Fri Nov 6, 9 AM, once Sean approves the text. Confirm the Monday access rule replaces the Oct 29 note.');
insert into public.bcps_assignment_notes (assignment_slug, note_text, author) select 'audit-followups-nov-3','Nov 5 Hot Lab: audit messages are too vague (Patricia Sapp: an image or contracts are flagged without saying what is wrong). Make every audit message name the specific problem and the fix. Still-stuck questions are not visible to Sean in navigation, so see audit-hub. Academics overview page is its own assignment.','Logan' where not exists (select 1 from public.bcps_assignment_notes where assignment_slug='audit-followups-nov-3' and note_text='Nov 5 Hot Lab: audit messages are too vague (Patricia Sapp: an image or contracts are flagged without saying what is wrong). Make every audit message name the specific problem and the fix. Still-stuck questions are not visible to Sean in navigation, so see audit-hub. Academics overview page is its own assignment.');
insert into public.bcps_assignment_notes (assignment_slug, note_text, author) select 'heading-sizes','Nov 5 Hot Lab (Sean): propose new heading sizes and mock them up side by side. Share the mock-ups with the District Web Team and WCMs at the Tuesday, Nov 10 Hot Lab. Check first whether heading sizes can be set site-wide, so no page needs touching. Then lock sizes and push. Also: a resource article on heading sizes in the resources section.','Logan' where not exists (select 1 from public.bcps_assignment_notes where assignment_slug='heading-sizes' and note_text='Nov 5 Hot Lab (Sean): propose new heading sizes and mock them up side by side. Share the mock-ups with the District Web Team and WCMs at the Tuesday, Nov 10 Hot Lab. Check first whether heading sizes can be set site-wide, so no page needs touching. Then lock sizes and push. Also: a resource article on heading sizes in the resources section.');
insert into public.bcps_assignment_notes (assignment_slug, note_text, author) select 'wcm-audits-departments','Nov 5 Hot Lab: the audit needs one home (audit-hub), on the District Web Team hub and visible to WCMs. Still-stuck questions were landing in a queue with no navigation link. Audit rule decisions stay hidden from WCMs (confirmed on the call).','Logan' where not exists (select 1 from public.bcps_assignment_notes where assignment_slug='wcm-audits-departments' and note_text='Nov 5 Hot Lab: the audit needs one home (audit-hub), on the District Web Team hub and visible to WCMs. Still-stuck questions were landing in a queue with no navigation link. Audit rule decisions stay hidden from WCMs (confirmed on the call).');
